// Local text editing and canvas-inline relation actions. No Host or model calls.
const fileItems=[{id:'benchmark',name:'推理评测方法.md',text:'# 推理评测方法\n\n示例资料，非真实研究结论。\n\n## 比较口径\n- 固定硬件与模型版本\n- 记录输入长度、并发和延迟\n- 性能与成本分别验证\n',node:'k:benchmark'},{id:'architecture',name:'部署架构笔记.md',text:'# 部署架构笔记\n\n示例资料。\n\n## 待确认\n- 部署边界\n- 数据同步范围\n- 试点负责人\n',node:'k:architecture'}];
let selectedRelation=null,editorDirty=false,editingId=null;
const relbar=document.createElement('div');relbar.id='relationbar';relbar.className='relationbar hide';relbar.setAttribute('role','region');relbar.setAttribute('aria-label','画布关联操作');$('.spacestage').append(relbar);
const evidenceDetail=edgeDetail;
edgeDetail=function(id){selectedRelation=id;const e=graphEdges.find(x=>x.id===id);relbar.replaceChildren();relbar.classList.remove('hide');const title=document.createElement('strong');title.textContent=e.label;relbar.append(title);const status=document.createElement('span');status.textContent={fact:'明确引用',suggested:'AI 判断 · 虚线',accepted:'已确认 · 实线',rejected:'已隐藏'}[e.state];relbar.append(status);function action(text,fn,primary=false){const b=document.createElement('button');b.className='btn'+(primary?' primary':'');b.textContent=text;b.onclick=fn;relbar.append(b)}if(e.state==='suggested'){action('✓ 确认',()=>setRelation(id,'accepted'),true);action('忽略',()=>setRelation(id,'rejected'))}if(e.state==='accepted'||e.state==='rejected')action('撤销',()=>setRelation(id,'suggested'));action('依据',()=>{let p=$('#inlineproof');if(p){p.remove();return}p=document.createElement('div');p.id='inlineproof';p.textContent=e.why+' 依据（示例）：'+e.source;relbar.append(p)});action('×',()=>{selectedRelation=null;relbar.classList.add('hide')});};
function setRelation(id,state){graphEdges.find(e=>e.id===id).state=state;drawSpace();edgeDetail(id);toast(state==='accepted'?'已确认：虚线变为实线，可撤销。仅当前页面有效。':state==='rejected'?'已忽略此建议，可撤销。':'已撤销，恢复 AI 虚线建议。')}
const drawBeforeV4=drawSpace;
drawSpace=function(){drawBeforeV4();const world=$('#spaceworld');if(!world)return;const shown=new Set(nodesShown().map(n=>n.id));graphEdges.filter(e=>e.state==='suggested'&&shown.has(e.a)&&shown.has(e.b)).forEach(e=>{const a=graphNodes.find(n=>n.id===e.a),b=graphNodes.find(n=>n.id===e.b),x=(a.x+b.x)/2+100,y=(a.y+b.y)/2+65;const g=se('g',{transform:`translate(${x} ${y})`,tabindex:0,role:'button','data-quickconfirm':e.id,'aria-label':'确认关联：'+e.label});g.append(se('rect',{x:-25,y:-11,width:50,height:23,rx:11,fill:'#edf4ff',stroke:'#88a9df'}),se('text',{'text-anchor':'middle',y:4,'font-size':10,fill:'#3466ae'},'✓ 确认'));world.append(g)});};
svg.addEventListener('pointerdown',e=>{if(e.target.closest('[data-quickconfirm]'))e.stopImmediatePropagation()},true);
svg.addEventListener('click',e=>{const q=e.target.closest('[data-quickconfirm]');if(q){e.stopPropagation();setRelation(q.dataset.quickconfirm,'accepted')}});
svg.addEventListener('keydown',e=>{const q=e.target.closest('[data-quickconfirm]');if(q&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.stopImmediatePropagation();setRelation(q.dataset.quickconfirm,'accepted')}},true);
function renderFiles(){active('#knowtabs','know','files');$('#knowbody').innerHTML='<div class="fileactions"><div><h2>文件与资料</h2><p>从项目与画布直接处理文件，不必跳回文件夹。</p></div><label class="btn filepick">选择本地文本<input type="file" id="localtext" accept=".md,.txt,.csv,.json,.log" hidden></label><button class="btn" id="newdoc">新建草稿</button></div><div class="resourcegrid" id="filecards"></div><div class="proof">文本：本页可编辑并导出副本。PDF / 图片：计划复用 DSH 预览。Office：计划适配已加载的 Univer 导入、编辑与导出工具；此页面没有嵌入 Office 编辑器。</div><p class="notice">选择文件只在本浏览器处理，不上传、不自动写回磁盘。草稿保留在当前页内，刷新会丢失，请导出副本。</p>';const cards=$('#filecards');fileItems.forEach(f=>{const b=document.createElement('button');b.className='surface resource';b.innerHTML=icon('doc');const h=document.createElement('h2');h.textContent=f.name;b.append(h);const p=document.createElement('p');p.textContent=f.local?'你选择的本地文本 · 未上传':'示例资料 · 可编辑副本';b.append(p);b.onclick=()=>editFile(f.id);cards.append(b)});$('#newdoc').onclick=()=>{const id='draft-'+Date.now();fileItems.push({id,name:'未命名草稿.md',text:'',local:true});renderFiles();editFile(id)};$('#localtext').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){toast('文本编辑演示限制为 2 MB，请选择更小的文件。');return}if(!/\.(md|txt|csv|json|log)$/i.test(file.name)){toast('请选择支持的文本文件。');return}try{const text=await file.text();if(text.includes('\u0000')){toast('检测到二进制内容，未打开。');return}const id='local-'+Date.now();fileItems.push({id,name:file.name,text,local:true});renderFiles();editFile(id)}catch{toast('读取失败，未修改原文件。')}}}
const knowledgeBeforeV4=renderKnowledge;renderKnowledge=function(mode){if(mode==='files')renderFiles();else knowledgeBeforeV4(mode)};
function editFile(id){const f=fileItems.find(x=>x.id===id);open(f.name,'FILE / 本地编辑演示','<div class="filemeta">浏览器内副本 · 不覆盖源文件 · 未上传</div><div class="editorbar"><span class="editorhint">内容编辑区</span><button class="btn" id="saveDraft">保存页内草稿</button><button class="btn primary" id="exportText">导出副本</button></div><textarea id="textEditor" spellcheck="false" aria-label="文本内容"></textarea><p id="editstate" role="status">未修改</p><div class="proof">正式接入：保存前核对原文件版本，显示冲突或差异；Office 通过受控工作树编辑与导出，不静默覆盖原件。</div>');editingId=id;$('#textEditor').value=f.text;$('#textEditor').oninput=()=>{editorDirty=true;$('#editstate').textContent='有未保存修改 · 可保存当前页草稿或导出副本'};$('#saveDraft').onclick=()=>{f.text=$('#textEditor').value;editorDirty=false;$('#editstate').textContent='已保存当前页草稿，刷新会丢失；原文件未改动'};$('#exportText').onclick=()=>{f.text=$('#textEditor').value;editorDirty=false;const u=URL.createObjectURL(new Blob([f.text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=f.name.replace(/(\.[^.]+)?$/,(_,ext)=>'-编辑副本'+(ext||'.txt'));a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('#editstate').textContent='已请求下载副本；请检查浏览器下载。原文件未改动'};}
const openBeforeV4=open;open=function(title,type,body){if(editingId&&editorDirty){const f=fileItems.find(x=>x.id===editingId);if($('#textEditor'))f.text=$('#textEditor').value;editorDirty=false;}editingId=null;openBeforeV4(title,type,body);const mapped=title==='推理评测方法'?'benchmark':title==='部署架构笔记'?'architecture':null;if(mapped){const bar=document.createElement('div');bar.className='modalactions';const b=document.createElement('button');b.className='btn primary';b.textContent='打开并编辑资料';b.onclick=()=>editFile(mapped);bar.append(b);$('#detailbody').append(bar)}else if(type.startsWith('PROJECT')){const bar=document.createElement('div');bar.className='modalactions';const b=document.createElement('button');b.className='btn';b.textContent='打开文件与资料';b.onclick=()=>{close();show('knowledge');renderFiles()};bar.append(b);$('#detailbody').append(bar)}};
const closeBeforeV4=close;close=function(){if(editingId&&$('#textEditor')){fileItems.find(x=>x.id===editingId).text=$('#textEditor').value;if(editorDirty)toast('已暂存到当前页草稿；刷新会丢失，请导出副本。')}editingId=null;editorDirty=false;closeBeforeV4()};$('.close').onclick=close;
window.addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue=''}});
const shortcut=document.createElement('button');shortcut.className='btn';shortcut.innerHTML=icon('doc')+'文件与资料';shortcut.onclick=()=>{show('knowledge');renderFiles()};$('.actions').insertBefore(shortcut,$('#assistant'));
$('#graphstatus').insertAdjacentHTML('afterend','<p class="canvasnotice">虚线旁直接点「✓ 确认」转实线；点连线显示轻操作条，可查依据、忽略或撤销，不强制打开弹窗。</p>');
